21	  const { data: metadata, isSuccess } = useLinkMetadata(url);
22	
23	  const title = metadata?.title.trim() ?? "";
24	  const description = metadata?.description.trim() ?? "";
25	  const image = metadata?.image.trim() ?? "";
26	  const hostname = getHostname(metadata?.url || url);
27	  const hasUsefulMetadata = title !== "" || description !== "";
28	
29	  useEffect(() => {
30	    setImageFailed(false);
